// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    PrivateBank c;
    RecordingLog log_;

    function setUp() public {
        log_ = new RecordingLog();
        c = new PrivateBank(address(log_));
        log_.setTarget(address(c));
    }

    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(log_));

        amount = bound(amount, 1 ether, type(uint128).max);
        vm.assume(depositor.balance == 0);
        vm.assume(address(c).balance <= type(uint128).max - amount);

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.Deposit{value: amount}();

        bytes32 expected = keccak256(abi.encode(depositor, amount, address(c), "ok"));
        assertTrue(log_.lastHash() == expected);
    }
}

contract RecordingLog {
    address public target;
    bytes32 public lastHash;

    function setTarget(address _target) external {
        target = _target;
    }

    function AddMessage(address _adr, uint _val, string memory _data) public {
        PrivateBank c = PrivateBank(payable(target));
        uint256 observedBalance = c.balances(_adr);
        bool coherent = observedBalance >= _val;
        lastHash = keccak256(abi.encode(_adr, _val, target, coherent ? "ok" : "bad"));
    }
}
